sys_ux_client_script_include.script:
function include({imports}) {
if (field.name === 'priority') {
        var priority = g_form.getValue('priority'); 
        var priorityColor = ''; 

        if (priority == 3) {
            priorityColor = 'yellow';
        } else if (priority == 2) {
            priorityColor = 'brown';
        } else if (priority == 1) {
            priorityColor = 'green';
        }else if (priority == 4) {
            priorityColor = 'orange';
        } else {
            priorityColor = 'gray';
        }

        g_form.setValue('priority_color', priorityColor);
    }
 }
